SELECT "__time" AS "time", "__c0" AS "sensor.ENERGY.Total" FROM (SELECT sub0.time AS "__time", (sub0.value - lag(sub0.value) OVER (ORDER BY sub0.time)) AS "__c0" FROM (SELECT time_bucket('1d', "time", 'Europe/Berlin') AS "time", avg("sensor.ENERGY.Total") AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "time" >= time_bucket('1d', time_bucket('1d', now(), 'Europe/Berlin') - interval '1 microsecond', 'Europe/Berlin') AND "time" < now() + interval '3d' GROUP BY 1 ORDER BY 1 ASC) sub0) d WHERE "__time" >= time_bucket('1d', now(), 'Europe/Berlin') ORDER BY 1 DESC